        {=ui_include('ui/link/link.latte', ['p' => ['Href' => '#/', 'Variant' => 'default', 'AriaCurrent' => ui_s((ui_t(ui_eq($v_current, 'home')) ? 'page' : null)), 'Attrs' => ui_attrs(['data-testid', 'nav-link'])], 'children' => $c_3])|noescape}
